def link_festivals(apps, schema_editor):
    """Festival events with a typed name and no festival get the festival of that name (found or created).
    Automatic titles ("Festival event") say nothing about which festival it is, so those are left alone."""
    Event = apps.get_model("events", "Event")
    Production = apps.get_model("events", "Production")
    for event in Event.objects.filter(event_type="festival", production=None, title_is_auto=False).exclude(title=""):
        title = " ".join(event.title.split())[:240]
        festival = Production.objects.filter(title__iexact=title).first()
        if festival is not None and festival.event_type != "festival":  # a tour already has that name
            title = f"{title[:228]} (festival)"
            festival = Production.objects.filter(title__iexact=title).first()
        if festival is None:
            festival = Production.objects.create(title=title, event_type="festival")
        Event.objects.filter(pk=event.pk).update(production=festival)


